def transform(grid):
    g = np.array(grid)
    out = g.copy()
    comps = components(g == 0, diagonal=False)
    table = {3: 1, 2: 2, 1: 3}
    sizes = sorted({len(c) for c in comps}, reverse=True)
    for s in sizes:
        col = table.get(s, max(1, 4 - s))
        for c in comps:
            if len(c) == s:
                for (y, x) in c:
                    out[y, x] = col
        emit(out, f"Recolour every 4-connected cluster of 0s with {s} cell(s) to colour {col}.")
    return out
